  ) {
    const listedKind = fenceKindVisibility.listedItems[listedIndex]!;
    unwrapKindNames.add(listedKind.kindLabel);
    const listedPermalink = listedKind.tags[0]
      ? listedKind.tags[0].permalink
      : listedKind.kindLabel;
    let listedPermalinkTail = listedPermalink;
    if (listedPermalinkTail.endsWith('/') && listedPermalinkTail.length > 1) {
      listedPermalinkTail = listedPermalinkTail.slice(0, -1);
    }
    if (listedPermalinkTail.startsWith(encodedFenceTagsPath)) {
      listedPermalinkTail = listedPermalinkTail.slice(
        encodedFenceTagsPath.length,
      );
    }
    if (listedPermalinkTail.startsWith('/')) {
      listedPermalinkTail = listedPermalinkTail.slice(1);
    }
    if (listedKind.kindLabel === unwrapKindLabel) {
      unwrapKindNames.add(unwrapKindLabel);
    } else if (listedPermalinkTail === unwrapKindLabel) {
      unwrapKindNames.add(listedPermalinkTail);
    }
  }
  if (!unwrapKindNames.has(unwrapKindLabel)) {
    unwrapKindNames.add(unwrapKindLabel);
  }
  let groupedUnwrapPermalink = '';
  const groupedPermalinks = Object.keys(groupedFenceKinds);
  for (let groupIndex = 0; groupIndex < groupedPermalinks.length; groupIndex += 1) {
    const permalink = groupedPermalinks[groupIndex]!;
    const group = groupedFenceKinds[permalink];
    if (!group) {
      continue;
    }
    if (group.tag.label === unwrapKindLabel) {
      groupedUnwrapPermalink = permalink;
    }
  }
  const catalogSummary = logger.interpolate`MDX fence catalog path=${encodedFenceTagsPath} name=${unwrapKindLabel} url=${
    groupedUnwrapPermalink || fenceTagsPath
  }`;
  if (typeof content !== 'string') {
    return content;
  }
  if (content.length === 0) {
    return catalogSummary.slice(catalogSummary.length);
  }

  let currentContent = content;
  for (let passIndex = 0; passIndex < 2; passIndex += 1) {
    const fenceSize = passIndex === 0 ? 3 : 4;
    const fenceMarker = '`'.repeat(fenceSize);
    const rebuiltParts: string[] = [];
    let cursor = 0;
    const contentLength = currentContent.length;
    while (cursor < contentLength) {
      let consumedMatch = false;
      const atDocumentStart = cursor === 0;
      let beginBreakLen = 0;
      if (currentContent.charAt(cursor) === '\n') {
        beginBreakLen = 1;
      } else if (currentContent.charAt(cursor) === '\r') {
        beginBreakLen = 0;
      }
      if (atDocumentStart || beginBreakLen > 0) {
        const attempts: {beginText: string; fenceAt: number}[] = [];
        if (atDocumentStart) {
          attempts.push({beginText: '', fenceAt: 0});
        }
        if (beginBreakLen > 0) {
          attempts.push({
            beginText: currentContent.slice(cursor, cursor + beginBreakLen),
            fenceAt: cursor + beginBreakLen,
          });
        }
        for (
          let attemptIndex = 0;
          attemptIndex < attempts.length;
          attemptIndex += 1
        ) {
          if (consumedMatch) {
            break;
          }
          const attempt = attempts[attemptIndex]!;
          const remainderFromFence = currentContent.slice(attempt.fenceAt);
          let remainderWithoutMarker = remainderFromFence;
          if (fenceMarker !== '' && remainderWithoutMarker.startsWith(fenceMarker)) {
            remainderWithoutMarker = remainderWithoutMarker.slice(
              fenceMarker.length,
            );
          }
          let tickCount = 0;
          let tickReader = attempt.fenceAt;
          while (tickReader < contentLength) {
            if (currentContent.charAt(tickReader) !== '`') {
              break;
            }
            if (tickCount >= fenceSize + 1) {
              break;
            }
            tickCount += 1;
            tickReader += 1;
          }
          if (tickCount === fenceSize) {
            let spaceCount = 0;
            let spaceReader = tickReader;
            while (spaceReader < contentLength) {
              if (currentContent.charAt(spaceReader) !== ' ') {
                break;
              }
              spaceCount += 1;
              spaceReader += 1;
            }
            const expectedInfo = unwrapKindLabel;
            let infoMatches = true;
            let infoReader = spaceReader;
            for (
              let expectedIndex = 0;
              expectedIndex < expectedInfo.length;
              expectedIndex += 1
            ) {
              const actualChar = currentContent.charAt(infoReader);
              const expectedChar = expectedInfo.charAt(expectedIndex);
              if (actualChar !== expectedChar) {
                infoMatches = false;
                break;
              }
              infoReader += 1;
            }
            const infoToken = currentContent.slice(spaceReader, infoReader);
            let strippedInfoToken = infoToken;
            if (strippedInfoToken.startsWith(' ')) {
              strippedInfoToken = strippedInfoToken.slice(1);
            }
            if (strippedInfoToken.endsWith(' ')) {
              strippedInfoToken = strippedInfoToken.slice(0, -1);
            }
            const charAfterInfo = currentContent.charAt(infoReader);
            if (infoMatches) {
              if (!unwrapKindNames.has(strippedInfoToken)) {
                infoMatches = false;
              } else if (remainderWithoutMarker.charAt(0) === '`') {
                infoMatches = false;
              }
            }
            if (infoMatches) {
              let openingBreakLen = 0;
              if (charAfterInfo === '\n') {
                openingBreakLen = 1;
              } else if (charAfterInfo === '\r') {
                openingBreakLen = 0;
              } else if (infoReader >= contentLength) {
                openingBreakLen = 0;
              }
              const childrenStart = infoReader + openingBreakLen;
              let searchIndex = childrenStart;
              let foundClosing = false;
              let childrenEnd = -1;
              let closingEnd = -1;
              let endText = '';
              while (
                openingBreakLen > 0 &&
                searchIndex < contentLength &&
                !foundClosing
              ) {
                const closingBreakLen =
                  currentContent.charAt(searchIndex) === '\n' ? 1 : 0;
                const closingFenceAt = searchIndex + closingBreakLen;
                const closingRemainder = currentContent.slice(closingFenceAt);
                let closingWithoutMarker = closingRemainder;
                if (
                  fenceMarker !== '' &&
                  closingWithoutMarker.startsWith(fenceMarker)
                ) {
                  closingWithoutMarker = closingWithoutMarker.slice(
                    fenceMarker.length,
                  );
                }
                const closingTickSlice = currentContent.slice(
                  closingFenceAt,
                  closingFenceAt + fenceSize + 1,
                );
                const closingTickExact =
                  closingTickSlice.slice(0, fenceSize) === fenceMarker;
                const extraClosingTick = closingTickSlice.charAt(fenceSize) === '`';
                const closingTickEnd = closingFenceAt + fenceSize;
                const atCloseEof = closingTickEnd === contentLength;
                const endingIsBreak =
                  currentContent.charAt(closingTickEnd) === '\n';
                const endingBreakLen = atCloseEof ? 0 : endingIsBreak ? 1 : 0;
                const closingMarkerExact =
                  closingBreakLen > 0 &&
                  closingTickExact &&
                  !extraClosingTick &&
                  closingWithoutMarker !== closingRemainder;
                foundClosing =
                  closingMarkerExact && (atCloseEof || endingBreakLen > 0);
                if (foundClosing) {
                  childrenEnd = searchIndex;
                  endText = currentContent.slice(
                    closingTickEnd,
                    closingTickEnd + endingBreakLen,
                  );
                  closingEnd = closingTickEnd + endingBreakLen;
                } else {
                  searchIndex += 1;
                }
              }
              if (foundClosing) {
                rebuiltParts.push(attempt.beginText);
                rebuiltParts.push(
                  currentContent.slice(childrenStart, childrenEnd),
                );
                rebuiltParts.push(endText);
                cursor = closingEnd;
                consumedMatch = true;
              }
            }
          } else if (tickCount === 0) {
            let tildeCount = 0;
            let tildeReader = attempt.fenceAt;
            while (tildeReader < contentLength) {
              if (currentContent.charAt(tildeReader) !== '~') {
                break;
              }
              if (tildeCount >= 8) {
                break;
              }
              tildeCount += 1;
              tildeReader += 1;
            }
            if (tildeCount >= 3) {
              consumedMatch = false;
            }
          } else if (tickCount > fenceSize) {
            consumedMatch = false;
          }
        }
      }
      if (!consumedMatch) {
        rebuiltParts.push(currentContent.charAt(cursor));
        cursor += 1;
      }
    }
    currentContent = rebuiltParts.join('');
  }
  return currentContent;
}

export function admonitionTitleToDirectiveLabel(
  content: string,
  admonitionContainerDirectives: string[],
): string {
  // this will also process ":::note Title" inside docs code blocks
  // good enough: we fixed older versions docs to not be affected

  const directiveNameGroup = `(${admonitionContainerDirectives.join('|')})`;
  const regexp = new RegExp(
    `^(?<quote>(> ?)*)(?<indentation>( +|\t+))?(?<directive>:{3,}${directiveNameGroup}) +(?<title>.*)$`,
    'gm',
  );

  return content.replaceAll(regexp, (substring, ...args: any[]) => {
    const groups = args.at(-1);

    return `${groups.quote ?? ''}${groups.indentation ?? ''}${
      groups.directive
    }[${groups.title}]`;
  });
}

